window.REPORT_PRELOAD_CACHE["BBWI.html"] = {"version":"15abbb74f3f0f43f74ed315d5a7347861c958c35983f76023b749e8e14150937","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Bath & Body Works Inc. (NYSE: BBWI) 深度研究报告：从美妆香氛零售龙头到数字化转型与股东价值重估</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    bbwblue: {\n                        400: '#38BDF8',\n                        500: '#00539F',\n                        600: '#003366',\n                    },\n                    accent: {\n                        500: '#3B82F6',\n                        600: '#2563EB',\n                    },\n                    teal: {\n                        500: '#06B6D4',\n                        600: '#0891B2',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n    ::-webkit-scrollbar {\n        width: 6px;\n        height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n        background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n        background: #94A3B8;\n        border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n        background: #475569;\n    }\n\n    @media print {\n        #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n            display: none !important;\n        }\n        main {\n            margin-left: 0 !important;\n            padding: 0 !important;\n        }\n        section {\n            break-inside: avoid;\n        }\n    }\n\n    .report-card {\n        transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n        transform: translateY(-2px);\n    }\n\n    .nav-link.active {\n        background: linear-gradient(90deg, rgba(0, 83, 159, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n        border-left: 3px solid #00539F;\n        color: #FFFFFF;\n        font-weight: 600;\n    }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-bbwblue-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-bbwblue-500 via-emerald-400 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-bbwblue-500 to-bbwblue-600 flex items-center justify-center font-extrabold text-white shadow\">\n                BB\n            </div>\n            <div>\n                <div class=\"text-[11px] text-bbwblue-400 font-semibold tracking-wider uppercase\">NYSE: BBWI · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">Bath & Body Works 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端折叠抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">BBWI 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n                    <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球美妆香氛与消费零售研究组</p>\n                <p class=\"mt-1\">数据基准：2026年11月 (2026 财年)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 机构品牌头 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-bbwblue-500 to-bbwblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-bbwblue-500/25\">\n                        BBWI\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-bbwblue-400 bg-bbwblue-500/15 px-2 py-0.5 rounded\">NYSE: BBWI</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">Bath & Body Works 研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    全球美妆香氛与个护龙头 · 高自由现金流与毛利重估标的\n                </p>\n            </div>\n\n            <!-- 股票实时快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">当前参考股价</span>\n                    <span class=\"font-mono font-bold text-white\">$21.39 <span class=\"text-bbwblue-400\">(+3.1%)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">2026 全年调整后 EPS</span>\n                    <span class=\"font-mono font-bold text-teal-400\">$2.60 – $2.80</span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">预期自由现金流</span>\n                    <span class=\"font-mono font-bold text-bbwblue-400\">~$650M (高自由现金流)</span>\n                </div>\n            </div>\n\n            <!-- 六个核心章节目录导航 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-bbwblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n                    </a>\n                    <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 侧边栏底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-bbwblue-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-bbwblue-500 hover:bg-bbwblue-600 text-white text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. Hero 研报封面区与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <!-- 顶部研报元数据标签栏 -->\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 font-bold border border-bbwblue-500/30\">评级：审慎增持 / 高自由现金流价值标的</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 战略转型、库存优化与数字化直销升级期</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NYSE: BBWI</span>\n                    </div>\n                </div>\n\n                <!-- Hero 标题卡片 -->\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#00539F 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-bbwblue-500/20 border border-bbwblue-500/40 text-bbwblue-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-bbwblue-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 垂直香氛个护品牌统治力 × 自由现金流上修至 $650M 与供应链效率提升</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            Bath & Body Works, Inc. (NYSE: BBWI) 深度研究报告：从美妆香氛零售龙头到数字化转型与股东价值重估\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            Bath & Body Works (BBWI) 作为全球个人护理与家居香氛领域的绝对领导者，在现任 CEO Daniel Heaf 带领下推进多年期增长战略。尽管 2026 财年被定位为转型与投资年（全年营收预期小幅微降 4% 至 2.5%），但公司凭借卓越的成本管控、<strong class=\"text-white\">全年自由现金流上修至 6.5 亿美元</strong>以及严格的库存清理（库存同比大降 10%），盈利超预期表现推动管理层多次上调全年调整后 EPS 指引至 <strong class=\"text-bbwblue-400\">$2.60–$2.80</strong>。\n                            当前动态 P/E 仅约 <strong class=\"text-teal-400\">5.5x–6.4x</strong>，叠加近 3.7% 的股息率与稳健现金流，估值安全边际极高。\n                        </p>\n\n                        <!-- 核心投资结论高亮条 -->\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">现金流大增与库存优化</div>\n                                <div class=\"text-white font-semibold\">全年自由现金流上修至 $650M，期末库存同比压降 10%，财务结构极度健康</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">盈利超预期与指引上调</div>\n                                <div class=\"text-bbwblue-400 font-semibold\">Q2 业绩超预期推动全年调整后 EPS 上修至 $2.60–$2.80，毛利率维持 43.3% 高位</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">极度吸引力的估值性价比</div>\n                                <div class=\"text-teal-400 font-semibold\">动态市盈率仅 ~6.0x，叠加近 3.7% 股息率与潜在诉讼/税收红利，下行风险充分释放</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <!-- KPI 1 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>当前股价 & 市值</span>\n                            <span class=\"p-1.5 rounded-lg bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$21.39</span>\n                            <span class=\"text-xs font-bold text-bbwblue-600 dark:text-bbwblue-400 bg-bbwblue-500/15 px-2 py-0.5 rounded\">市值 $4.31B</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            股价在 52 周区间 ($14.28 – $24.94) 中筑底回升，具备显著的价值重估潜力。\n                        </p>\n                    </div>\n\n                    <!-- KPI 2 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>2026 调整后 EPS 预期</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$2.60–$2.80</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">P/E ~6.4x</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            Q2 业绩超预期后管理层上调盈利指引，全年毛利率预期保持在 43.3% 稳健水平。\n                        </p>\n                    </div>\n\n                    <!-- KPI 3 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>预期自由现金流</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$650M</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">FCF 强劲</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            得益于运营现金流优化 ($890M) 与资本开支纪律 ($240M)，自由现金流指引大幅上修。\n                        </p>\n                    </div>\n\n                    <!-- KPI 4 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>股息率与总回报</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~3.7%</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">总回报 ~7.15%</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            持续派发稳定季度股息，结合高现金流收益率，为长期价值投资者提供优异的现金回报。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            一、 业务与收入架构 (Business & Revenue Architecture)\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-bbwblue-600 dark:text-bbwblue-400\">Section 01 · Business & Revenue Architecture</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：香氛、身体护理与直销/门店双轮驱动</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">全年营收规模 ~$7.2B · 直销渠道稳健增长</span>\n                </div>\n\n                <!-- 交互式 Chart.js 双视图切换面板 -->\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <!-- 左侧：双视图图表 -->\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026 核心品类与渠道营收演进</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">家居香氛与身体护理基本盘稳固，Direct (数字直销) 渠道持续复苏</p>\n                            </div>\n                            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                                <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-bbwblue-600 dark:text-bbwblue-400 shadow-sm transition\">视图A：年度营收演进</button>\n                                <button onclick=\"switchBizChart('margin')\" id=\"btn-chart-mar\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：毛利与现金流表现</button>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：结构性拆解核心洞察 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性转型</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">标志性香氛与身体护理基本盘</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            涵盖标志性身体乳、沐浴露、洗手液及知名家用香氛蜡烛（Three-Wick Candles）。凭借高复购率与强情感连接，构筑起难以撼动的品类心智。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">数字直销（Direct Net Sales）逆势增长</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            在整体销售指引小幅下调（-4% 至 -2.5%）的背景下，数字直销渠道实现近年来首次直接增长，得益于过去一年数字体验与APP端优化的持续回报。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">供应链精简与一次性财务增益</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            2026 年业绩包含约 8,800 万美元互换费诉讼和解收益、约 8,000 万美元关税退税及 6,200 万美元税收优惠，大幅增厚当期现金与盈利。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心转型抓手</span>\n                            <span class=\"font-bold text-bbwblue-600 dark:text-bbwblue-400\">产品创新、需求创造与库存精准把控</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 核心业务板块矩阵卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-bbwblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 text-xs font-bold\">核心品类 · 身体护理</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">高复购率基本盘</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">个人与身体护理 (Body Care)</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            包含全系列香水喷雾、身体乳霜与清洁洗手液。通过高频推陈出新与节日限定香型，持续激发消费者的收藏与冲动购买欲望。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">家居美学 · 家居香氛</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">蜡烛与扩香器龙头</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">家居香氛 (Home Fragrance)</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            以经典三芯蜡烛（Three-Wick Candles）与 Wallflowers 墙壁扩香器闻名全球，在美国家庭香氛市场占据无可动摇的统治地位。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between mb-3\">\n                            <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">渠道升级 · 数字直销</span>\n                            <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">APP与全渠道融合</span>\n                        </div>\n                        <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">数字直销与实体零售</h3>\n                        <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                            实体专卖店网络与数字化APP、官网无缝协同，提供全方位的会员忠诚度计划与个性化精准营销。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            二、 行业地位与四重核心护城河 (Industry Position & Moat)\n            ========================================================= -->\n            <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：品牌心智、垂直供应链与高毛利结构</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽护城河 (Wide Moat · 垂直细分香氛个护标杆)</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <!-- 左侧：四重护城河深度解析 -->\n                    <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">无可替代的情感化香氛品牌心智</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                历经数十年积累，BBWI 在消费者心中已等同于“生活仪式感与节日香氛”。高频的季节性香型更迭形成极强的粉丝黏性与冲动消费驱动力。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的垂直一体化产品开发与毛利空间</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                绝大部分产品采用自有研发与精细化代工结合，全年预计调整后毛利率高达 43.3%，在消费零售板块具备顶级的盈利基础。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极佳的库存纪律与营运资本周转</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                2026 年通过严密的供应链规划，期末库存同比大幅压降 10%，前瞻性清理库存积压，保障了高达 6.5 亿美元的纯净自由现金流流入。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全渠道忠诚度生态与直销转化</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                庞大的会员体系与数字化营销平台实现精准触达，推动数字直销业务在行业逆风中实现近年首次直接转正增长。\n                            </p>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：五维护城河雷达图 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">香氛个护行业五维护城河量化雷达图</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">BBWI vs 美妆综合集团 vs 垂直平价美妆零售商（满分 10 分）</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"moatRadarChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            三、 同行竞争格局横向对比 (Competitive Landscape)\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-bbwblue-600 dark:text-bbwblue-400\">Section 03 · Global Competitive Landscape</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：垂直香氛龙头 vs 美妆综合与个护巨头</h2>\n                    </div>\n                    <!-- 交互式筛选按钮 -->\n                    <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n                        <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-bbwblue-500 text-white shadow-sm transition\">全部阵营</button>\n                        <button onclick=\"filterCompetitors('fragrance')\" data-filter=\"fragrance\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">垂直香氛与美妆零售</button>\n                        <button onclick=\"filterCompetitors('conglomerate')\" data-filter=\"conglomerate\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">综合美妆与个护集团</button>\n                    </div>\n                </div>\n\n                <!-- 横向对比矩阵表格 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心品牌</th>\n                                    <th class=\"py-4 px-4 min-w-[130px]\">主营赛道与定位</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">估值与 P/E 特征</th>\n                                    <th class=\"py-4 px-4 min-w-[135px]\">毛利率水平</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                                <tr data-category=\"fragrance\" class=\"bg-bbwblue-500/5 dark:bg-bbwblue-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-bbwblue-500 text-white text-[10px] font-extrabold\">垂直龙头</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">Bath & Body Works (BBWI)</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球家居香氛与身体护理龙头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">身体护理、洗手液、家居香氛蜡烛</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-900 dark:text-white\">~5.5x - 6.4x (极低估值)</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-bbwblue-600 dark:text-bbwblue-400\">~43.3% (调整后高毛利)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>超高自由现金流：</strong>估值倍数处于历史底部，全年 $650M FCF 支撑强劲股息与现金回报。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"fragrance\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">Ulta Beauty (ULTA)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">美国美妆集合店巨头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">多品牌美妆、护肤与沙龙服务</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~23.85x P/E</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~38% - 40%</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>美妆零售渠道权威：</strong>品牌矩阵极广，但估值受美妆行业整体竞争加剧影响较 BBWI 更高。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"conglomerate\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">雅诗兰黛 Estée Lauder (EL)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球高端美妆与奢华香水集团</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高端护肤、彩妆与高端沙龙香水</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~38.01x P/E (周期波动)</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~70%+ (高端奢华毛利)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>高端奢华定位：</strong>主打高端免税与百货渠道，近期业绩复苏斜率与供应链波动较 BBWI 更复杂。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- 配套 Chart.js 横向条形图：毛利率与估值对比 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">美妆与个护行业主要厂商估值与盈利特征对比</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">BBWI 拥有约 43.3% 的高毛利率，而其动态 P/E 仅约 6.4x，估值性价比在同行中极为突出</p>\n                        </div>\n                        <span class=\"text-xs font-semibold text-bbwblue-600 dark:text-bbwblue-400 bg-bbwblue-500/15 px-2.5 py-1 rounded\">极具安全边际的估值优势</span>\n                    </div>\n                    <div class=\"relative h-60 w-full\">\n                        <canvas id=\"compMarginChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：自由现金流上修至 $650M 与极低 P/E</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">动态 P/E ~6.4x · 现金及等价物 $794M</span>\n                </div>\n\n                <!-- 1. 财务健康度四大硬核指标卡 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-bbwblue-600 dark:text-bbwblue-400 uppercase\">Gross Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">43.3%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            全预期调整后毛利率稳居 43.3% 高位，包含部分关税退税带来的积极效益。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Free Cash Flow</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$650M</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            全年自由现金流预测上修至 6.5 亿美元（基于 $890M 经营现金流减去 $240M 资本开支）。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Cash Reserve</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$794M</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            期末现金及现金等价物达 7.94 亿美元，显著高于去年同期的 3.64 亿美元，流动性极为充沛。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Valuation P/E</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~6.4x</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            相比美妆与个护行业平均估值，BBWI 当前动态 P/E 具备极具吸引力的安全边际。\n                        </p>\n                    </div>\n                </div>\n\n                <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026 营收规模与自由现金流（FCF）演进趋势</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">战略转型期营收保持稳健，库存清理与营运资本优化驱动自由现金流飙升至 $650M</p>\n                        </div>\n                        <span class=\"text-xs font-mono font-bold text-bbwblue-600 dark:text-bbwblue-400 bg-bbwblue-500/10 px-2.5 py-1 rounded\">2026 FCF 指引 ~$650M</span>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- 3. 互动式复利推演计算器 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n                        <div>\n                            <h3 class=\"text-lg font-bold text-white\">Bath & Body Works (BBWI) 投资回报与复利推演器</h3>\n                            <p class=\"text-xs text-slate-400 mt-1\">模拟在不同盈利增速与估值修复预期下的长期持仓市值与复合回报率</p>\n                        </div>\n                        <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-bbwblue-300 border border-slate-700\">交互式推演模型</span>\n                    </div>\n\n                    <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n                        <div class=\"space-y-5\">\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n                                    <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n                                </div>\n                                <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-bbwblue-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">持有年限 (Years)</span>\n                                    <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n                                </div>\n                                <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-bbwblue-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n                                    <span id=\"grVal\" class=\"font-bold text-bbwblue-400\">6.0%</span>\n                                </div>\n                                <input id=\"grSlider\" type=\"range\" min=\"0\" max=\"18\" step=\"0.5\" value=\"6.0\" class=\"w-full accent-bbwblue-400 cursor-pointer\">\n                            </div>\n                        </div>\n\n                        <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n                                <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$23,820</div>\n                                <div id=\"totalGainPct\" class=\"text-xs text-bbwblue-400 mt-1\">累计总回报 +19.1%</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n                                <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$25.50</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">基于基本面修复与估值回归</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n                                <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">6.0%</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">稳健现金流与高股息收益</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            五、 投资决策与风险配置框架 (Investment Decision & Risk)\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-bbwblue-600 dark:text-bbwblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：消费组合中兼具高现金回报与估值修复弹性的标的</span>\n                </div>\n\n                <!-- 1. 三情景估值推演卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-bbwblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-bbwblue-600 dark:text-bbwblue-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">估值目标：10x – 12x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>2026 投资年转型顺利，2027 营收恢复正增长，数字化直销表现超越预期，自由现金流持续稳居 $700M+，估值向历史均值回归。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-bbwblue-600 dark:text-bbwblue-400\">\n                            潜在上行空间：+50% 至 +75%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">估值目标：8x – 9x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>全年营收小幅下滑 2.5%–4%，但调整后 EPS 稳守 $2.60–$2.80 指引，自由现金流达成 $650M，估值获得温和修复。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                            潜在上行空间：+20% 至 +35%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御估值：5x – 5.5x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>终端消费需求超预期疲软导致销售额降幅超指引，一次性关税退税及诉讼和解收益后续无法对冲日常运营压力。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-10% 至 -15% (受高股息支撑)\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 2. 四大核心风险评估矩阵 -->\n                <div>\n                    <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 终端消费零售需求疲软风险</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">可选消费品复苏斜率低于预期</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                沐浴露、身体乳与蜡烛属于典型的可选消费品，若宏观经济导致非刚需消费缩减，可能对全年销售额带来持续压制。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 一次性收益不可持续风险</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">非经常性损益对财报的扰动</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                2026 年报表中的互换费诉讼和解收益及关税退税属于一次性非经常项目，投资者需剥离此类噪音，关注核心内生业务毛利。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 数字化转型与投资回报周期</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">转型投资年对短期利润的压制</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                2026 作为战略投资年，在产品创新与需求创造上的持续资本开支若未能迅速转化成2027年营收正增长，可能引发市场担忧。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 供应链与原材料价格波动</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：低中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">香精原料与包装包材成本波动</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                化妆品与家居香氛所需的化工原料及蜡烛包材若遭遇供应链价格反复，可能对 43.3% 的毛利率目标形成阶段性挤压。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-bbwblue-500/15 text-bbwblue-600 dark:text-bbwblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <!-- KPI 1 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Q3 财报业绩能否达标（指引净销售额下降 5% 至 2.5%）</span>\n                                    <span class=\"text-[11px] font-mono text-bbwblue-600 dark:text-bbwblue-400 font-semibold shrink-0\">短期销售验证</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪 2026 年 11 月 19 日公布的 Q3 财报，验证净销售额及调整后 EPS（预测 $0.07–$0.12）是否符合预期。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 2 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 全年自由现金流 $650M 指引的最终兑现率</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">现金流硬指标</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    持续监督运营现金流（目标 $890M）与资本开支（控制在 $240M）的实际达成情况。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 3 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 库存健康度（维持同比压降 10% 或更优水平）</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">库存健康监控</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    检查各季资产负债表中的库存余额，确保无严重滞销库存积压，保障毛利率稳定性。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 4 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 数字直销（Direct Net Sales）增长势头能否延续</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">线上复苏引擎</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪 APP 端活跃度、数字化会员复购率及线上销售额是否继续保持正增长。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 5 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 调整后毛利率是否维持在 43.3% 目标轨道</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">盈利能力防线</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    核查剔除一次性关税退税后，核心商品的毛利率是否保持稳健。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 6 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#00539F] focus:ring-bbwblue-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 长期债务压降与资本配置规划（股息与回购动态）</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">资产负债优化</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    关注公司利用充沛现金流进一步削减长期债务及未来重启股份回购的战略节点。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            页脚免责声明 (Disclaimer Footer)\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>Bath & Body Works, Inc. (NYSE: BBWI) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n                    <span>数据基准：2026 年财报及 2026 年 11 月最新市场资讯</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、SEC 8-K 文件及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n    <script>\n    function toggleTheme() {\n        const html = document.documentElement;\n        html.classList.toggle('dark');\n        updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n        const drawer = document.getElementById('mobile-drawer');\n        drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n        const scrollTop = window.scrollY;\n        const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n        const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n        document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n        let currentId = 'sec-exec';\n        sections.forEach(sec => {\n            const top = sec.offsetTop - 160;\n            if (scrollTop >= top) {\n                currentId = sec.getAttribute('id');\n            }\n        });\n\n        navLinks.forEach(link => {\n            link.classList.remove('active');\n            const numSpan = link.querySelector('span span');\n            if (numSpan) {\n                numSpan.classList.remove('text-bbwblue-400');\n                numSpan.classList.add('text-slate-500');\n            }\n            if (link.dataset.target === currentId) {\n                link.classList.add('active');\n                if (numSpan) {\n                    numSpan.classList.remove('text-slate-500');\n                    numSpan.classList.add('text-bbwblue-400');\n                }\n            }\n        });\n    });\n\n    function filterCompetitors(category) {\n        document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n            if (btn.dataset.filter === category) {\n                btn.classList.add('bg-bbwblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            } else {\n                btn.classList.remove('bg-bbwblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            }\n        });\n\n        const rows = document.querySelectorAll('#comp-table-body tr');\n        rows.forEach(row => {\n            const rowCat = row.dataset.category;\n            if (category === 'all' || rowCat === category) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    }\n\n    const KPI_STORAGE_KEY = 'bbwi_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n        try {\n            const saved = localStorage.getItem(KPI_STORAGE_KEY);\n            if (saved) {\n                const stateMap = JSON.parse(saved);\n                document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                    if (typeof stateMap[cb.id] === 'boolean') {\n                        cb.checked = stateMap[cb.id];\n                    }\n                });\n            }\n        } catch (e) {}\n        updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n        const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n        const total = checkboxes.length;\n        let checkedCount = 0;\n        const stateMap = {};\n\n        checkboxes.forEach(cb => {\n            stateMap[cb.id] = cb.checked;\n            if (cb.checked) checkedCount++;\n        });\n\n        const pct = Math.round((checkedCount / total) * 100);\n        document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n        try {\n            localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n        } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n        document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            cb.checked = false;\n        });\n        updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'revenue';\n\n    function getChartColors() {\n        const isDark = document.documentElement.classList.contains('dark');\n        return {\n            text: isDark ? '#CBD5E1' : '#475569',\n            grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n            radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n        };\n    }\n\n    function initBizChart() {\n        const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n        const colors = getChartColors();\n\n        const revConfig = {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', '2026(E)'],\n                datasets: [\n                    {\n                        label: '实体门店与零售营收 ($B)',\n                        data: [5.8, 5.5, 5.4, 5.3],\n                        backgroundColor: '#00539F',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: '数字直销与国际营收 ($B)',\n                        data: [1.8, 1.9, 1.9, 1.95],\n                        backgroundColor: '#3B82F6',\n                        borderRadius: 4,\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        stacked: true,\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        stacked: true,\n                        max: 8.5,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        const marConfig = {\n            type: 'line',\n            data: {\n                labels: ['2023', '2024', '2025', '2026(E)'],\n                datasets: [\n                    {\n                        label: '调整后毛利率 Gross Margin (%)',\n                        data: [42.0, 42.5, 43.0, 43.3],\n                        borderColor: '#00539F',\n                        backgroundColor: '#00539F',\n                        borderWidth: 3,\n                        pointRadius: 5,\n                        tension: 0.25,\n                        yAxisID: 'y'\n                    },\n                    {\n                        label: '自由现金流 Free Cash Flow ($M)',\n                        data: [450, 520, 580, 650],\n                        borderColor: '#10B981',\n                        backgroundColor: '#10B981',\n                        borderWidth: 3,\n                        pointRadius: 5,\n                        tension: 0.25,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: ${ctx.parsed.y}%`\n                                : `${ctx.dataset.label}: $${ctx.parsed.y}M`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        min: 35,\n                        max: 50,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 300,\n                        max: 800,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'M' }\n                    }\n                }\n            }\n        };\n\n        if (bizChartInstance) bizChartInstance.destroy();\n        bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : marConfig);\n    }\n\n    function switchBizChart(mode) {\n        currentBizMode = mode;\n        const btnRev = document.getElementById('btn-chart-rev');\n        const btnMar = document.getElementById('btn-chart-mar');\n        const titleEl = document.getElementById('biz-chart-title');\n        const subEl = document.getElementById('biz-chart-sub');\n\n        if (mode === 'revenue') {\n            btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-bbwblue-600 dark:text-bbwblue-400 shadow-sm transition';\n            btnMar.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '2023–2026 核心品类与渠道营收演进';\n            subEl.textContent = '家居香氛与身体护理基本盘稳固，Direct (数字直销) 渠道持续复苏';\n        } else {\n            btnMar.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-bbwblue-600 dark:text-bbwblue-400 shadow-sm transition';\n            btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = '2023–2026 调整后毛利率与自由现金流表现';\n            subEl.textContent = '供应链优化与库存严控驱动毛利率与自由现金流超预期增长';\n        }\n        initBizChart();\n    }\n\n    function initRadarChart() {\n        const ctx = document.getElementById('moatRadarChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (radarChartInstance) radarChartInstance.destroy();\n        radarChartInstance = new Chart(ctx, {\n            type: 'radar',\n            data: {\n                labels: [\n                    '垂直香氛品牌心智与忠诚度',\n                    '垂直供应链与高毛利结构',\n                    '库存纪律与营运资本周转',\n                    '数字直销APP与全渠道触达',\n                    '季节性产品创新与节日营销'\n                ],\n                datasets: [\n                    {\n                        label: 'Bath & Body Works (BBWI)',\n                        data: [9.6, 9.4, 9.0, 8.5, 9.5],\n                        borderColor: '#00539F',\n                        backgroundColor: 'rgba(0, 83, 159, 0.22)',\n                        pointBackgroundColor: '#00539F',\n                        borderWidth: 2.5\n                    },\n                    {\n                        label: '美妆集合店与大卖场竞品',\n                        data: [7.5, 7.0, 7.2, 8.0, 7.0],\n                        borderColor: '#3B82F6',\n                        backgroundColor: 'rgba(59, 130, 246, 0.14)',\n                        pointBackgroundColor: '#3B82F6',\n                        borderWidth: 1.8\n                    },\n                    {\n                        label: '传统百货个护品牌',\n                        data: [6.0, 6.5, 6.0, 5.5, 6.2],\n                        borderColor: '#94A3B8',\n                        backgroundColor: 'rgba(148, 163, 184, 0.12)',\n                        pointBackgroundColor: '#94A3B8',\n                        borderWidth: 1.5,\n                        borderDash: [4, 4]\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n                    }\n                },\n                scales: {\n                    r: {\n                        min: 0,\n                        max: 10,\n                        ticks: { display: false, stepSize: 2 },\n                        grid: { color: colors.grid },\n                        angleLines: { color: colors.radarAngle },\n                        pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initCompMarginChart() {\n        const ctx = document.getElementById('compMarginChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (compMarginChartInstance) compMarginChartInstance.destroy();\n        compMarginChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: [\n                    'Estée Lauder (EL · 高端奢华美妆)',\n                    'Bath & Body Works (BBWI · 香氛个护龙头)',\n                    'Ulta Beauty (ULTA · 美妆集合零售)',\n                    '传统美妆日化平均水平'\n                ],\n                datasets: [{\n                    label: '毛利率 Gross Margin (%)',\n                    data: [72.5, 43.3, 39.0, 40.0],\n                    backgroundColor: [\n                        '#3B82F6',\n                        '#00539F',\n                        '#06B6D4',\n                        '#64748B'\n                    ],\n                    borderRadius: 6,\n                    barThickness: 24\n                }]\n            },\n            options: {\n                indexAxis: 'y',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `毛利率: ${ctx.parsed.x}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        max: 85,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initValEvolutionChart() {\n        const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n        valEvolutionChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: ['2023', '2024', '2025', '2026(E)'],\n                datasets: [\n                    {\n                        type: 'bar',\n                        label: '全年总营收 ($B)',\n                        data: [7.56, 7.43, 7.29, 7.15],\n                        backgroundColor: 'rgba(0, 83, 159, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 28,\n                        yAxisID: 'y'\n                    },\n                    {\n                        type: 'bar',\n                        label: '自由现金流 FCF ($M)',\n                        data: [450, 520, 580, 650],\n                        backgroundColor: 'rgba(16, 185, 129, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 28,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                                : `${ctx.dataset.label}: $${ctx.parsed.y}M`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        max: 9.0,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 0,\n                        max: 800,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'M' }\n                    }\n                }\n            }\n        });\n    }\n\n    function updateChartsTheme() {\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n    }\n\n    // Calculator Logic\n    const invSlider = document.getElementById('invSlider');\n    const yrSlider = document.getElementById('yrSlider');\n    const grSlider = document.getElementById('grSlider');\n\n    function updateCalculator() {\n        const principal = parseFloat(invSlider.value);\n        const years = parseInt(yrSlider.value);\n        const growthRate = parseFloat(grSlider.value) / 100;\n\n        document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n        document.getElementById('yrVal').textContent = years + ' 年';\n        document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n        const finalVal = principal * Math.pow(1 + growthRate, years);\n        const totalGain = finalVal - principal;\n        const gainPct = (totalGain / principal) * 100;\n        const impliedPrice = 21.39 * Math.pow(1 + growthRate * 0.85, years);\n\n        document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n        document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n        document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n        document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n    }\n\n    [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n    window.addEventListener('DOMContentLoaded', () => {\n        loadKpiChecklist();\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n        updateCalculator();\n    });\n    </script>\n</body>\n</html>\n"};
